import{_ as t,o as i,c as n,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Le Dictionnaire de Terminologie","description":"","frontmatter":{},"headers":[],"relativePath":"fr/0090-术语词典.md","filePath":"fr/0090-术语词典.md"}'),r={name:"fr/0090-术语词典.md"};function d(a,e,o,l,u,c){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="le-dictionnaire-de-terminologie" tabindex="-1">Le Dictionnaire de Terminologie <a class="header-anchor" href="#le-dictionnaire-de-terminologie" aria-label="Permalink to &quot;Le Dictionnaire de Terminologie&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>90</td></tr><tr><td>Module</td><td>Annexes et documents de référence</td></tr><tr><td>Mots clés</td><td>dictionnaire de terminologie, concepts centraux, définitions, terminologie unifiée, Univers Hengyuan</td></tr></tbody></table><h2 id="i-notes-de-terminologie" tabindex="-1">I. Notes de Terminologie <a class="header-anchor" href="#i-notes-de-terminologie" aria-label="Permalink to &quot;I. Notes de Terminologie&quot;">​</a></h2><p>Ce dictionnaire recense les termes centraux du système de l&#39;univers de la Civilisation Symbiotique de l&#39;Ancre, visant à unifier l&#39;usage des termes dans tous les documents et à garantir la cohérence et la précision de l&#39;expression conceptuelle. Tous les termes sont classés selon la première lettre de leur pinyin chinois ; chaque entrée contient le nom du terme, le nom de référence anglais (le cas échéant), la définition et une brève explication. Ce dictionnaire est un document à mise à jour dynamique ; à mesure que le système de l&#39;univers s&#39;étend, de nouveaux termes seront continuellement ajoutés.</p><h2 id="ii-le-tableau-des-termes-centraux" tabindex="-1">II. Le Tableau des Termes Centraux <a class="header-anchor" href="#ii-le-tableau-des-termes-centraux" aria-label="Permalink to &quot;II. Le Tableau des Termes Centraux&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N°</th><th>Terme</th><th>Définition et explication</th></tr></thead><tbody><tr><td>1</td><td>Ancre</td><td>Un nœud stable du réseau de lois, servant de référence de coordonnées pour maintenir la stabilité des lois des plans, réaliser les connexions interplans et la régression temporelle. En essence, une Ancre est un condensé à haute densité des lois originelles de l&#39;univers à un emplacement spatial spécifique, possédant la capacité d&#39;auto-maintien et de calibration.</td></tr><tr><td>2</td><td>Civilisation Symbiotique de l&#39;Ancre</td><td>Une forme de civilisation fondée sur le mécanisme de l&#39;Ancre comme base technique et sur l&#39;évolution symbiotique comme concept central. Elle s&#39;oppose au système de culture prédatrice et préconise de rendre aux êtres vivants le choix du destin et de l&#39;évolution, réalisant ainsi : plus de travail, plus de gain ; croissance autonome ; une voie pour chacun ; la progression commune des Dix Mille Races.</td></tr><tr><td>3</td><td>Univers Hengyuan</td><td>L&#39;abréviation de l&#39;« Univers Originel Wanling Hengmao », l&#39;étendue cosmique entière où la Civilisation Symbiotique de l&#39;Ancre demeure et gouverne. C&#39;est un être composite constitué de quatre niveaux : les plans matériels, la couche d&#39;énergie, le domaine de la conscience et le réseau de lois.</td></tr><tr><td>4</td><td>Univers Originel Wanling Hengmao</td><td>Le nom complet de l&#39;Univers Hengyuan. « Wanling » (Dix Mille Esprits) désigne toutes les formes de vie possédant un potentiel de perception et d&#39;évolution ; « Hengmao » (Ancres d&#39;équilibre) désigne le mécanisme de l&#39;Ancre qui maintient l&#39;équilibre cosmique ; « Univers Originel » souligne les attributs essentiels de prendre les lois originelles comme fondement et l&#39;évolution symbiotique comme direction.</td></tr><tr><td>5</td><td>Symbiose</td><td>L&#39;un des concepts centraux de la Civilisation Symbiotique de l&#39;Ancre, désignant l&#39;évolution commune d&#39;individus, de races et de civilisations différentes par une coopération mutuellement bénéfique, plutôt qu&#39;une évolution prédatrice au détriment d&#39;autrui.</td></tr><tr><td>6</td><td>Système de culture prédatrice</td><td>Une méthode de culture qui réalise l&#39;auto-évolution en dévorant l&#39;énergie, la fortune et même l&#39;origine des faibles. C&#39;est le type de système que la Civilisation Symbiotique de l&#39;Ancre rejette fermement, considéré comme la cause profonde de l&#39;accélération de l&#39;entropie cosmique et de la fréquence des ruptures civilisationnelles.</td></tr><tr><td>7</td><td>Les Trois Cents Systèmes de Culture d&#39;Origine</td><td>Des voies de culture orthodoxes directement extraites des lois originelles de l&#39;univers et vérifiées par les Ancres, au nombre de trois cents, réparties en six grandes catégories : déduction d&#39;origine, cycle de vie, principes juridiques spatiaux, élévation de la conscience, réseau symbiotique et ingénierie appliquée, avec cinquante systèmes par catégorie.</td></tr><tr><td>8</td><td>Les Trois Fondations d&#39;Origine</td><td>Les trois premiers systèmes fondamentaux parmi les trois cents systèmes — le Système d&#39;Itération par Déduction (n° 1), le Système de Cycle de Vie (n° 2) et le Système de Régulation des Principes Juridiques Spatiaux (n° 3) — la base de culture de tous les autres systèmes.</td></tr><tr><td>9</td><td>Système d&#39;Itération par Déduction</td><td>Le système de culture d&#39;origine n° 1, caractérisé par une amplification centuple de la déduction de culture, utilisant l&#39;application technique du Fruit Multiplicateur pour porter la capacité de déduction au centuple, soulignant l&#39;optimisation des voies de culture par la déduction, la vérification et l&#39;itération.</td></tr><tr><td>10</td><td>Système de Cycle de Vie</td><td>Le système de culture d&#39;origine n° 2, centré sur le cycle vertueux de l&#39;énergie vitale, soulignant que l&#39;échange d&#39;énergie entre le cultivateur et l&#39;environnement doit être cyclique et non prédateur.</td></tr><tr><td>11</td><td>Système de Régulation des Principes Juridiques Spatiaux</td><td>Le système de culture d&#39;origine n° 3, centré sur la compréhension et la régulation des lois spatiales, la base de culture d&#39;applications importantes telles que l&#39;interaction interplans, la construction d&#39;espaces isolés et la technologie du Miroir de Réplication.</td></tr><tr><td>12</td><td>Fruit Multiplicateur</td><td>Le Fruit Multiplicateur originaire du monde de One Piece, techniquement appliqué dans l&#39;Univers Hengyuan, capable de porter la capacité de déduction du cultivateur au centuple, l&#39;outil auxiliaire central du Système d&#39;Itération par Déduction. L&#39;un des buffs de départ.</td></tr><tr><td>13</td><td>Mécanisme de contrat lié à la production</td><td>Le mécanisme de répartition des ressources de la Civilisation Symbiotique de l&#39;Ancre, distribuant les ressources de culture cosmique aux individus ou aux groupes sous forme de « contrat » ; les contractants obtiennent le droit d&#39;usage des ressources par le travail et la contribution, réalisant ainsi plus de travail, plus de gain.</td></tr><tr><td>14</td><td>Stratégie d&#39;activation de 20 %</td><td>L&#39;objectif stratégique par étapes de la Civilisation Symbiotique de l&#39;Ancre : activer dans la phase initiale 20 % des êtres vivants de l&#39;univers pour qu&#39;ils deviennent des Puissances Suprêmes des Plans, les utilisant comme ossature pour entraîner l&#39;évolution commune des 80 % d&#39;êtres vivants restants.</td></tr><tr><td>15</td><td>Puissance Suprême du Plan</td><td>Un puissant qui a cultivé jusqu&#39;à un niveau extrêmement élevé et peut maintenir de manière indépendante la stabilité des lois d&#39;un plan. C&#39;est la cible de la stratégie d&#39;activation de 20 % et une force d&#39;entretien importante du réseau de l&#39;Ancre.</td></tr><tr><td>16</td><td>Réseau de lois</td><td>Le quatrième niveau de la structure de l&#39;Univers Hengyuan, le fondement opérationnel des lois originelles de l&#39;univers et la base racine des Ancres. Le réseau de lois traverse tout l&#39;univers et constitue la base technique de toutes les opérations de lois (y compris la régulation spatiale, la régression temporelle et la transformation de l&#39;énergie).</td></tr><tr><td>17</td><td>Plan</td><td>Une région d&#39;existence définie par un ensemble relativement stable de lois, possédant une continuité spatio-temporelle indépendante. Chaque plan possède des constantes physiques, une densité d&#39;énergie, une vitesse d&#39;écoulement du temps et un niveau d&#39;activité de conscience uniques.</td></tr><tr><td>18</td><td>Barrière de lois</td><td>La barrière de lois séparant les plans adjacents, dont la force dépend du degré de différence entre les paramètres de lois des plans adjacents. La navigation interplans exige de surmonter les barrières de lois.</td></tr><tr><td>19</td><td>Empreinte de lois</td><td>Un identifiant unique généré par opération de hachage sur les paramètres de lois centraux de chaque plan, d&#39;une longueur de 128 bits, l&#39;un des paramètres centraux du système de coordonnées des plans.</td></tr><tr><td>20</td><td>Observer d&#39;abord, puis intervenir dans les limites</td><td>Le principe opérationnel premier de la régression temporelle et de l&#39;archéologie interplans, exigeant que toute régression ou toute archéologie accomplisse d&#39;abord la phase d&#39;observation pure et, après confirmation de l&#39;absence de risques majeurs, ne procède qu&#39;à une intervention limitée.</td></tr><tr><td>21</td><td>Miroir de Réplication</td><td>Un dispositif de réplication de haute précision fondé sur les lois des principes juridiques spatiaux, capable de réaliser une réplication complète 1:1 de la zone cible sans toucher l&#39;original, l&#39;équipement central du schéma d&#39;archéologie hors site.</td></tr><tr><td>22</td><td>Espace isolé</td><td>Une région de lois indépendante construite par la technologie de régulation des principes juridiques spatiaux, utilisée pour porter les copies archéologiques et servir de lieu de travail aux archéologues, complètement séparée de l&#39;univers externe par des barrières de lois.</td></tr><tr><td>23</td><td>Restitution de connaissances uniquement</td><td>Le principe central du protocole archéologique, signifiant que pendant le processus archéologique, seules les connaissances et informations abstraites peuvent être obtenues de l&#39;objet cible ; aucun matériau, aucune énergie ni aucun être vivant ne peut être restitué.</td></tr><tr><td>24</td><td>Purification de l&#39;information</td><td>Le processus technique consistant à dépouiller complètement les empreintes de lois du plan d&#39;origine portées dans les informations brutes et à ne conserver que le contenu sémantique pur, le maillon clé pour garantir la sécurité des connaissances restituées.</td></tr><tr><td>25</td><td>Paradoxe temporel</td><td>Le phénomène par lequel la logique causale devient contradictoire en raison d&#39;un comportement d&#39;interférence pendant les opérations de régression temporelle, comprenant les quatre grandes catégories : paradoxe du parricide, paradoxe informationnel, paradoxe ontologique et paradoxe événementiel.</td></tr><tr><td>26</td><td>Chaîne causale</td><td>La structure linéaire continue des causes et des conséquences entre les événements, un concept central des lois du temps. Le risque central des opérations de régression temporelle est la perturbation de la chaîne causale.</td></tr><tr><td>27</td><td>Constitution Symbiotique</td><td>La loi fondamentale de la Civilisation Symbiotique de l&#39;Ancre, possédant la plus haute force juridique, établissant le fond civilisationnel de lutte contre la prédation et de promotion de la symbiose, ainsi que les sept principes constitutionnels fondamentaux.</td></tr><tr><td>28</td><td>Égalité des Dix Mille Races</td><td>L&#39;un des sept principes fondamentaux de la Constitution Symbiotique, signifiant que toutes les formes de vie, quelle que soit leur race, leur niveau de culture ou leur origine, sont égales devant la loi.</td></tr><tr><td>29</td><td>Vie anomale</td><td>Des formes de vie ne correspondant pas à la définition conventionnelle de la vie et possédant des formes d&#39;existence spéciales, exigeant une identification et une gestion selon les procédures de traitement standardisées en trois catégories.</td></tr><tr><td>30</td><td>Énergie anomale</td><td>Des formes d&#39;énergie ne correspondant pas à la classification conventionnelle de l&#39;énergie et possédant des attributs et des schémas de comportement spéciaux, exigeant une classification et un contrôle selon les procédures de traitement standardisées en trois catégories.</td></tr><tr><td>31</td><td>Entité de Substitution Obscure</td><td>Une forme de vie spéciale impliquant la question éthique de la coexistence de deux âmes, exigeant une gestion selon les Directives Éthiques des Deux Âmes et les règles de traitement des quatre branches.</td></tr><tr><td>32</td><td>Directives Éthiques des Deux Âmes</td><td>Des directives éthiques pour l&#39;état de coexistence de deux âmes au sein d&#39;une Entité de Substitution Obscure, dont le cœur est le respect des droits respectifs des deux âmes et l&#39;interdiction de la fusion forcée ou de l&#39;élimination de l&#39;une des parties.</td></tr><tr><td>33</td><td>Les Cinq Typologies de Civilisations Symbiotiques</td><td>Cinq types de sociétés symbiotiques divisées selon les caractéristiques des civilisations du monde réel : le type intensif d&#39;Asie de l&#39;Est, le type providence nordique, le type pluraliste nord-américain, le type social d&#39;Europe continentale et le type de rattrapage en développement.</td></tr><tr><td>34</td><td>La Voie d&#39;Élévation en Quatre Étapes</td><td>La route en quatre étapes pour l&#39;élévation globale de l&#39;Univers Hengyuan : fondation sur la réalité → autonomisation technologique → évolution de la conscience → symbiose interstellaire.</td></tr><tr><td>35</td><td>La réalité comme fondement</td><td>L&#39;une des positions fondamentales de la Civilisation Symbiotique de l&#39;Ancre, signifiant que le monde réel est le seul monde réel, que les mondes romanesques sont des expériences de pensée fausses, que la fiction est complétée par la réalité lorsqu&#39;elle est insuffisante, et que ce que la réalité ne possède pas est créé par une élévation fondée sur les lois.</td></tr><tr><td>36</td><td>Indice de symbiose</td><td>Un indicateur quantitatif évaluant le degré d&#39;intégration d&#39;une civilisation ou d&#39;un individu au réseau symbiotique, couvrant plusieurs dimensions telles que le degré de partage des ressources, la fréquence de collaboration et la proportion de comportements altruistes.</td></tr><tr><td>37</td><td>Assemblée Délibérante de l&#39;Ancre</td><td>L&#39;organe suprême de pouvoir de la Civilisation Symbiotique de l&#39;Ancre, composé de représentants des Dix Mille Races en proportion, exerçant le pouvoir législatif et le pouvoir de décision des affaires majeures.</td></tr><tr><td>38</td><td>Comité Exécutif Symbiotique</td><td>L&#39;organe administratif suprême de la Civilisation Symbiotique de l&#39;Ancre, chargé de l&#39;exécution de la constitution et des lois et de la gouvernance quotidienne.</td></tr><tr><td>39</td><td>Tribunal Symbiotique</td><td>L&#39;organe judiciaire suprême de la Civilisation Symbiotique de l&#39;Ancre, exerçant de manière indépendante le pouvoir de juger, chargé du contrôle de constitutionnalité et du jugement des affaires majeures.</td></tr><tr><td>40</td><td>Administration des Plans</td><td>Un organe spécialisé sous l&#39;Assemblée Délibérante de l&#39;Ancre, chargé de l&#39;entretien de la base principale des coordonnées des plans, de l&#39;approbation des permis de navigation et de la gestion de l&#39;archéologie interplans.</td></tr></tbody></table><h2 id="iii-normes-d-usage-de-la-terminologie" tabindex="-1">III. Normes d&#39;Usage de la Terminologie <a class="header-anchor" href="#iii-normes-d-usage-de-la-terminologie" aria-label="Permalink to &quot;III. Normes d&#39;Usage de la Terminologie&quot;">​</a></h2><ol><li>Les termes recensés dans ce dictionnaire sont des termes standard ; tous les documents doivent privilégier les expressions standard de ce dictionnaire.</li><li>Le même concept doit utiliser le même terme dans les différents documents ; les synonymes ne doivent pas être substitués arbitrairement.</li><li>Les nouveaux termes générés dans les nouveaux univers doivent être soumis rapidement au Comité de Terminologie pour examen et ajoutés au dictionnaire après approbation.</li><li>Si la définition d&#39;un terme est révisée, la version la plus récente de ce dictionnaire prévaut, et le contenu de la révision doit également être consigné dans les notes de version du document.</li><li>Lorsqu&#39;on cite un terme, le nom complet peut être utilisé à sa première apparition et l&#39;abréviation par la suite, mais la clarté du sens dans le contexte doit être assurée.</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Le dictionnaire de terminologie est la pierre angulaire linguistique de tout le système de l&#39;univers. Le système terminologique unifié garantit la cohérence conceptuelle entre les cent documents, permettant aux lecteurs de passer sans heurt d&#39;un module à l&#39;autre sans ambiguïté de compréhension. À mesure que le système de l&#39;univers s&#39;enrichit et se perfectionne, ce dictionnaire sera continuellement mis à jour, servant toujours de source terminologique faisant autorité pour tous les documents.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Heng Yuan Zhou : Vue d&#39;ensemble du Cosmos)</li><li>02-锚点本源定义与本质 (Définition et Essence de l&#39;Origine de l&#39;Ancre)</li><li>99-文档版本与维护说明 (Notes de version et de maintenance des documents)</li></ul>',12)])])}const g=t(r,[["render",d]]);export{p as __pageData,g as default};
